const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pages={projects:['▦','프로젝트'],story:['✎','기획'],timeline:['▥','타임라인'],images:['▧','캐릭터·이미지'],video:['▷','영상·검수'],settings:['⚙','연결과 설정'],palette:['◉','컬러 & 디자인']};
const fresh=()=>({title:'마지막 열차',synopsis:'매일 같은 역에서 마지막 열차를 기다리는 사진가 윤. 어느 날, 10년 전 자신이 보낸 엽서를 든 여행자를 만난다. 두 사람은 사라져 가는 작은 역을 사진에 담으며, 미뤄 두었던 각자의 여행을 시작한다.',duration:300,analyzed:false,storyApproved:false,timelineApproved:false,imageApproved:false,candidate:0,imageProvider:'Grok Imagine',mode:'혼합',orchestration:'역할 고정',primary:'OpenAI · 구독 모델',tab:'시놉시스',settingsTab:'계정·모델',selected:0,statuses:Array(20).fill('waiting'),retry:false,connections:[],auth:{},pipeline:['Ollama · 로컬 모델','LM Studio · 로컬 모델'],enhanced:false});
let state=fresh();try{Object.assign(state,JSON.parse(localStorage.getItem('framepop-demo')||'{}'));state.statuses=state.statuses.map(s=>['generating','internal','boundary'].includes(s)?'waiting':s)}catch{}let running=false,timer=null;
const save=()=>localStorage.setItem('framepop-demo',JSON.stringify(state));const toast=t=>{$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2600)};
const photo=(cls='scene-img')=>`<img class="${cls}" src="assets/station.png" alt="파란 재킷을 입은 캐릭터 윤과 파스텔색 기차역의 데모 장면">`;
const time=n=>`${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;
const names=['낯익은 플랫폼','도착한 엽서','처음 보는 얼굴','열차가 머무는 시간','작은 역의 이야기','사진 속의 우리','다시 만난 시선','느린 걸음','닫힌 매표소','남겨 둔 약속','노을의 편지','같은 풍경','떠날 준비','마지막 인사','푸른 시간','열차의 불빛','나란한 두 사람','다음 역으로','멀어지는 플랫폼','새로운 첫 장'];
function go(p){location.hash=p}function page(){return pages[location.hash.slice(1)]?location.hash.slice(1):'story'}
function heading(k,title,sub,action=''){return `<div class="heading"><div><div class="eyebrow">${k}</div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`}
function steps(i){return `<div class="steps">${['이야기 만들기','타임라인','레퍼런스','영상 & QC'].map((s,n)=>`<div class="step ${n===i?'current':n<i?'done':''}"><i>${n<i?'✓':n+1}</i>${s}</div>`).join('')}</div>`}
function options(values,current){return values.map(v=>`<option ${v===current?'selected':''}>${esc(v)}</option>`).join('')}
function render(){const p=page();$('#breadcrumb').textContent=pages[p][1];$('#nav').innerHTML=Object.entries(pages).filter(([k])=>!['settings','palette'].includes(k)).map(([k,[icon,label]],i)=>`<button data-page="${k}" class="${p===k?'active':''}"><span>${icon}</span>${label}<span class="num">${i+1}</span></button>`).join('');$('#main').innerHTML=views[p]();save()}
const views={
projects:()=>heading('YOUR LITTLE FILM CLUB','다음 이야기는 뭘까요?','이어 만들거나, 새로운 한 편을 시작해 보세요.','<button class="primary" data-action="new">＋ 새 프로젝트</button>')+`<div class="grid3"><article class="card project-card">${photo()}<div class="caption"><span class="pill blue">${esc(state.mode)}</span><h2 style="margin:13px 0">${esc(state.title)}</h2><p class="muted">${time(state.duration)} · ${state.statuses.length} 세그먼트 · 24 fps</p><div class="actions"><small>이 브라우저에 저장됨</small><button data-page="story">계속 만들기 ↗</button></div></div></article><button class="card" data-action="new" style="min-height:330px;border-style:dashed"><span class="spark">＋</span><h2 style="margin:15px">새로운 아이디어</h2><p class="muted">한 줄의 시놉시스부터 시작해요.</p></button></div>`,
story:()=>heading('LET’S MAKE A STORY','머릿속 장면을, 이야기로.','시놉시스를 적어 주세요. 한 편으로 이어질 수 있게 함께 정리해요.',`<span class="pill blue">✦ ${esc(state.mode)} 작업실</span>`)+steps(0)+`<div class="columns"><section class="card"><div class="card-head"><h2>01 &nbsp; 어떤 이야기인가요?</h2><span class="pill">초안 ${state.analyzed?'v2':'v1'}</span></div><div class="tabs">${['시놉시스','플롯·스토리'].map(t=>`<button data-tab="${t}" class="${state.tab===t?'active':''}">${t}</button>`).join('')}</div>${state.tab==='시놉시스'?`<div class="field"><label for="title">프로젝트 이름</label><input id="title" data-field="title" value="${esc(state.title)}"></div><div class="field"><div class="row between"><label for="synopsis">시놉시스</label><small>가볍게 적어도 괜찮아요</small></div><textarea id="synopsis" data-field="synopsis" rows="7">${esc(state.synopsis)}</textarea><small style="text-align:right;margin-top:6px">${state.synopsis.length}자 · 직접 수정 가능</small></div><div class="fields"><div><label for="duration">목표 재생 시간</label><select id="duration" data-field="duration">${[60,90,180,300].map(n=>`<option value="${n}" ${state.duration===n?'selected':''}>${n/60}분 · ${Math.ceil(n/15)} 세그먼트</option>`).join('')}</select></div><div><label for="mode">실행 경로</label><select id="mode" data-field="mode">${options(['혼합','로컬 전용','클라우드'],state.mode)}</select></div></div><div class="actions"><span class="help">✦ ${state.orchestration} · ${state.mode==='로컬 전용'?'로컬 모델':'Primary LLM'}</span><button class="primary" data-action="analyze">✧ 이야기 구체화</button></div>`:state.analyzed?`<p class="help">입력한 시놉시스를 바탕으로 편집 가능한 데모 초안을 만들었어요.</p>${['도입 · 마지막 열차를 기다리는 윤','전개 · 오래된 엽서를 따라 걷다','결말 · 미뤄 둔 여행의 시작'].map((t,i)=>`<div class="story-beat"><span class="beat-num">0${i+1}</span><div><h3>${t}</h3><textarea aria-label="${t}" data-beat="${i}" rows="2">${esc(state.beats?.[i]||[state.synopsis,'여행자와 함께 역의 흔적을 기록하며, 엽서에 담긴 약속을 알아간다.','두 사람은 마지막 열차에 오른다. 같은 풍경이 새로운 시작이 된다.'][i])}</textarea></div></div>`).join('')}<div class="actions"><button data-action="analyze">다시 구체화</button><button class="primary" data-action="approveStory">스토리 확정 →</button></div>`:`<div class="empty"><span class="spark">✧</span><p>시놉시스를 먼저 구체화해 주세요.</p><button data-tab="시놉시스">시놉시스 쓰기</button></div>`}</section><aside><section class="card"><div class="card-head"><h2>이야기의 첫 장면</h2><span class="pill">MOOD PREVIEW</span></div><div class="image-wrap">${photo()}<span class="image-label">데모 레퍼런스</span><div class="image-bottom"><small>A LITTLE JOURNEY</small><h2>${esc(state.title)}</h2></div></div><div class="mini-stats"><div><small>러닝타임</small><strong>${time(state.duration)}</strong></div><div><small>등장인물</small><strong>2명</strong></div><div><small>영상 구간</small><strong>${state.statuses.length}개</strong></div></div><p class="help">익숙한 장소에서 시작되는 작은 여행.<br>따뜻한 빛과 푸른 저녁의 색을 담아 볼까요?</p></section><div class="callout"><span class="spark">✳</span><div><h3>이야기는 자유롭게, 진행은 차근차근.</h3><p>스토리와 레퍼런스를 확정한 뒤 영상을 만들어요.</p></div></div></aside></div>`,
timeline:()=>heading('PUT IT IN MOTION','장면마다, 딱 좋은 호흡.','샷을 선택해 길이와 순서를 조정하세요. 기본 생성 단위는 15초예요.',`<button class="primary" data-action="approveTimeline">타임라인 확정 →</button>`)+steps(1)+`<div class="card"><div class="card-head"><h2>${esc(state.title)} <span class="pill">24 fps</span></h2><span class="pill ${state.storyApproved?'green':'orange'}">${state.storyApproved?'✓ 스토리 확정':'스토리 확정 필요'}</span></div><div class="columns"><div class="image-wrap">${photo()}<span class="image-label">S${String(state.selected+1).padStart(2,'0')} · 장면 프리뷰</span></div><div><div class="eyebrow">SEGMENT ${String(state.selected+1).padStart(2,'0')}</div><h2>${names[state.selected%20]}</h2><p class="muted" style="margin:16px 0">플랫폼의 따뜻한 빛 아래, 윤이 엽서를 바라본다. 카메라는 천천히 가까워진다.</p><label>길이 (초)</label><input id="clipDuration" type="number" min="1" max="30" value="${state.lengths?.[state.selected]||15}"><div class="row" style="margin-top:14px"><button data-action="saveLength">길이 적용</button><button data-action="moveLeft">← 앞으로</button><button data-action="moveRight">뒤로 →</button></div><div class="note">현재 합계 ${time(totalLength())} / 목표 ${time(state.duration)}<br>${totalLength()===state.duration?'✓ 목표 길이와 딱 맞아요.':'목표 길이에 맞춰 조정해 주세요.'}</div></div></div><div class="timeline">${state.statuses.map((_,i)=>`<button class="clip ${i===state.selected?'selected':''}" data-select="${i}">${photo('')}<strong>S${String(i+1).padStart(2,'0')} · ${state.lengths?.[i]||15}초</strong><small>${names[i%20]}</small></button>`).join('')}</div></div>`,
images:()=>heading('MEET YOUR CHARACTER','이 이야기의 얼굴을 골라요.','이미지를 만들고, 마음에 드는 모습을 영상과 Face QC의 기준으로 확정하세요.',`<button class="primary" data-action="approveImage">레퍼런스 확정 →</button>`)+steps(2)+`<div class="card"><div class="row between"><div class="row"><span class="modelmark">☺</span><div><h3>윤 · 사진가</h3><small>28세 · 짧은 단발 · 파란 재킷</small></div></div><span class="pill ${state.timelineApproved?'green':'orange'}">${state.timelineApproved?'타임라인 확정':'타임라인 확정 필요'}</span></div><div class="fields" style="margin-top:22px"><div><label>이미지 생성 모델</label><select data-field="imageProvider">${options(['Grok Imagine','GPT-Image-2.5','ComfyUI · 로컬'],state.imageProvider)}</select></div><div><label>프롬프트 강화</label><select><option>Ollama → LM Studio · 로컬</option><option>Primary LLM</option></select></div></div><div class="field" style="margin-top:20px"><label>이미지 프롬프트</label><textarea id="imagePrompt" rows="2">${esc(state.imagePrompt||'파란 재킷을 입은 단발의 사진가 윤. 작은 기차역, 따뜻하고 자연스러운 얼굴, 부드러운 저녁 빛.')}</textarea></div><div class="row between"><span class="help">${state.enhanced?'✓ 구도·광원·캐릭터 유지 조건 보강됨':'캐릭터의 얼굴과 의상은 유지하며 묘사를 더해요.'}</span><div class="row"><button data-action="enhance">✧ 프롬프트 강화</button><button class="primary" data-action="generateImage">후보 이미지 만들기</button></div></div></div><div class="blankspace"></div><div class="grid3">${['따뜻한 첫인상','차분한 시선','선명한 순간'].map((t,i)=>`<article class="candidate ${state.candidate===i?'selected':''}" tabindex="0" role="button" data-candidate="${i}" aria-label="${t} 선택">${photo('')}<span class="badge">${state.candidate===i?'✓':'○'}</span><div class="caption"><div class="row between"><h3>${t}</h3><span class="pill">후보 0${i+1}</span></div><small>데모 이미지 · ${esc(state.imageProvider)} 선택 프리뷰</small></div></article>`).join('')}</div><div class="note">확정한 참조 이미지 v${state.imageApproved?1:0} → ComfyUI 영상 입력 + 세그먼트별 Face QC 기준<br>클라우드에서 만든 레퍼런스를 로컬에서 사용해도, 로컬 영상이 클라우드로 다시 전송되지는 않아요.</div>`,
video:()=>{let done=state.statuses.filter(s=>s==='pass').length,s=state.statuses[state.selected],failed=s==='fail';return heading('ONE SEGMENT AT A TIME','한 장면씩, 제대로 이어서.','생성 → 얼굴·구간 검수 → 연결부 검수. 통과하면 다음 세그먼트가 시작돼요.',`<div class="row"><button data-action="pause">${running?'잠시 멈추기':'일시정지'}</button><button class="primary" data-action="start">${done?'이어서 생성':'영상 생성 시작'} ▷</button></div>`)+steps(3)+`<div class="card"><div class="row between"><h3>${done} / ${state.statuses.length} 세그먼트 확정</h3><span class="pill ${state.imageApproved?'green':'orange'}">${state.imageApproved?'✓ 참조 v1 연결':'레퍼런스 확정 필요'}</span></div><div class="progress"><div style="width:${done/state.statuses.length*100}%"></div></div><div class="segments">${state.statuses.map((st,i)=>`<button class="seg ${st==='pass'?'pass':st==='fail'?'fail':['generating','internal','boundary'].includes(st)?'work':''} ${i===state.selected?'sel':''}" data-select="${i}">${st==='pass'?'✓ ':st==='fail'?'! ':''}${String(i+1).padStart(2,'0')}</button>`).join('')}</div><p class="help" style="margin-top:15px">${running?'● 순차 실행 중':state.statuses.includes('fail')?'! QC 확인이 필요해요. 이후 세그먼트는 대기 중입니다.':done===state.statuses.length?'✓ 모든 세그먼트 검수 완료 · 조립 확인을 할 수 있어요.':'○ 준비되면 시작해 주세요.'} · 모든 상태는 데모입니다.</p></div><div class="blankspace"></div><div class="columns"><div class="card"><div class="card-head"><h2>S${String(state.selected+1).padStart(2,'0')} · ${names[state.selected%20]}</h2><span class="pill ${failed?'orange':'blue'}">${statusName(s)}</span></div><div class="image-wrap">${photo()}<span class="image-label">${time(state.selected*15)} — ${time((state.selected+1)*15)} · 스틸 프리뷰</span></div><div class="phase">생성 <span>→</span> <strong>Face QC</strong> <span>→</span> 연결부 <span>→</span> 확정</div><button data-action="preview">▷ 장면 카드 프리뷰</button><p class="help" style="margin-top:12px">실제 영상 렌더링 대신 장면 카드로 흐름을 미리 봅니다.</p></div><div class="card"><div class="card-head"><h2>Face & continuity check</h2><span class="pill">로컬 QC</span></div><div class="split-preview"><div>${photo('')}<small>${state.selected?'이전 세그먼트 끝부분':'확정 캐릭터 기준 v1'}</small></div><div>${photo(failed?'risk':'')}<small>현재 세그먼트 시작부분</small></div></div><div class="checks"><div class="check"><span>캐릭터 기준 일치</span><b>${s==='pass'?'✓ 통과':failed?'✓ 기준 유지':'검사 대기'}</b></div><div class="check"><span>구간 내부 얼굴 품질</span><b style="color:${failed?'var(--orange)':'inherit'}">${failed?'! 얼굴 선명도 확인':s==='pass'?'✓ 통과':'검사 대기'}</b></div><div class="check"><span>직전 연결부</span><b>${!state.selected?'적용 제외':s==='pass'?'✓ 통과':failed?'재검사 필요':'이전 QC 대기'}</b></div></div>${failed?'<div class="note">데모 결함 · 01:34 부근 얼굴 선명도 저하<br>7번만 재생성합니다. 8번 이후는 통과할 때까지 기다려요.</div>':''}<div class="actions"><small>판정·프레임은 예시 데이터</small><button data-action="retry" ${!['fail','pass'].includes(s)?'disabled':''}>이 세그먼트 재생성</button></div></div></div>`},
palette:()=>heading('A BRIGHT LITTLE SYSTEM','가볍게, 또렷하게, Framepop.','화이트 여백에 블루의 집중력, 라임의 즐거움, 핑크의 온기를 더했어요.','<button data-action="downloadPalette">컬러 차트 다운로드 ↓</button>')+`<div class="swatches">${[['Electric blue','#3155F5','주요 버튼 · 선택 · 진행'],['Lime pop','#DFFF82','작은 기쁨 · 안내 포인트'],['Candy pink','#FFB7DB','캐릭터 · 개성 · 포인트'],['Paper white','#FFFFFF','카드 · 작업 표면'],['Cloud gray','#F7F8FA','전체 배경'],['Soft ink','#20252B','제목 · 본문'],['Forest','#177556','QC 통과 · 연결 성공'],['Amber','#A85212','검토 필요 · 재시도']].map(([n,h,use])=>`<div class="swatch"><div class="color" style="background:${h};color:${['#3155F5','#20252B','#177556','#A85212'].includes(h)?'white':'#20252B'}">${n}</div><div class="caption"><h3>${n}</h3><small>${use}</small><button data-copy="${h}">${h} ⧉</button></div></div>`).join('')}</div><div class="blankspace"></div><div class="columns"><div class="card"><div class="eyebrow">TYPE & VOICE</div><h1>작은 아이디어를 한 편으로.</h1><p class="muted" style="margin:18px 0">DM Sans + Noto Sans KR<br>친근한 문장, 분명한 다음 행동. 꾸미기보다 만들기에 집중해요.</p><div class="row"><button class="primary">이야기 시작하기</button><button class="lime">좋아요, 확정!</button></div></div><div class="card"><div class="eyebrow">STATUS LANGUAGE</div><h2>색만으로 설명하지 않아요.</h2><div class="row" style="margin:22px 0;flex-wrap:wrap"><span class="pill green">✓ QC 통과</span><span class="pill orange">! 검토 필요</span><span class="pill blue">◷ 생성 중</span></div><p class="help">상태에는 항상 텍스트를 함께 표시합니다. 밝은 라임과 핑크 위에는 어두운 글자를 사용해 읽기 편하게 구성했어요.</p></div></div>`,
settings:()=>heading('MAKE IT YOURS','도구는 연결하고, 방식은 내 취향대로.','계정과 로컬 모델, 프롬프트 구성, 생성 서버를 한곳에서 관리해요.')+`<div class="tabs">${['계정·모델','작업 배정','생성 서버','전송 정책'].map(t=>`<button data-settings-tab="${t}" class="${state.settingsTab===t?'active':''}">${t}</button>`).join('')}</div>`+settingsBody()
};
function settingsBody(){switch(state.settingsTab){case '계정·모델':return `<div class="card"><div class="card-head"><h2>구독 계정</h2><span class="pill">실제 로그인 없는 데모</span></div><div class="setting-grid">${['OpenAI','xAI'].map((n,i)=>`<div class="connection"><div class="row"><span class="modelmark">${i?'𝕏':'✺'}</span><div><h3>${n}</h3><small>${i?'Grok 구독 · 기기 코드':'ChatGPT / Codex 구독'}</small></div></div><div class="blankspace"></div><span class="pill ${state.auth[n]?'green':''}">${state.auth[n]?'✓ 데모 연결됨':'연결 전'}</span><small>이미지 모델의 구독 사용 가능 여부는 별도 확인</small><button data-auth="${n}">${state.auth[n]?'연결 해제':'구독 계정 연결 ↗'}</button></div>`).join('')}</div></div><div class="card"><div class="card-head"><h2>Open-weight 모델 서버</h2><button data-action="addServer">＋ 서버 등록</button></div><div class="setting-grid">${[{name:'Ollama',url:'http://localhost:11434'},{name:'LM Studio',url:'http://localhost:1234'},...state.connections].map((c,i)=>`<div class="connection"><h3>${esc(c.name)}</h3><small>${esc(c.url)}</small><span class="pill blue">로컬 실행 서버 기준</span><div class="row"><button data-test="${i}">연결 검사</button><button data-models="${i}">모델 조회</button>${i>1?`<button data-delete="${i-2}">삭제</button>`:''}</div></div>`).join('')}</div><div class="note">로컬 전용 프로젝트에서는 Primary와 검토 역할까지 로컬에서 실행해요. 실패해도 클라우드로 자동 전송하지 않습니다.</div></div>`;
case '작업 배정':return `<div class="columns"><div class="card"><h2>누가 어떤 일을 할까요?</h2><div class="field" style="margin-top:22px"><label>배정 방식</label><select data-field="orchestration">${options(['역할 고정','Primary 자동 배정'],state.orchestration)}</select></div><label>Primary 모델</label><select data-field="primary">${options(state.mode==='로컬 전용'?['Ollama · 로컬 모델','LM Studio · 로컬 모델']:['OpenAI · 구독 모델','xAI · 구독 모델','Ollama · 로컬 모델','LM Studio · 로컬 모델'],state.primary)}</select><div class="roles">${['시놉시스 분석','플롯·스토리','샷 설계','프롬프트 강화','일관성 검토'].map((n,i)=>`<label>${n}</label><select data-role="${i}">${options(state.mode==='로컬 전용'?['Ollama · 로컬 모델','LM Studio · 로컬 모델']:['OpenAI · 구독 모델','xAI · 구독 모델','Ollama · 로컬 모델','LM Studio · 로컬 모델'],state.roles?.[i]||(i>2?'Ollama · 로컬 모델':'OpenAI · 구독 모델'))}</select>`).join('')}</div><div class="note">${state.orchestration==='역할 고정'?'Primary가 지정된 모델에 작업을 맡겨요.':'Primary가 허용된 모델 안에서 담당자를 선택해요.'} 공통 규칙 + Primary 지침 + 작업별 명세를 분리합니다.</div></div><div class="card"><h2>프롬프트 강화 구성</h2><p class="help" style="margin:14px 0">실제 이미지 생성 모델과 별도로 선택해요.</p>${state.pipeline.map((m,i)=>`<div class="field"><label>STEP ${i+1} · ${i?'검토·정리':'시각적 묘사 강화'}</label><select data-pipeline="${i}">${options(['Ollama · 로컬 모델','LM Studio · 로컬 모델'],m)}</select></div>`).join('')}<label>Primary 지침</label><textarea data-field="primaryPrompt" rows="7">${esc(state.primaryPrompt||'사용자의 의도와 확정된 캐릭터 설정을 보존한다. 필요한 작업을 분해하고 허용된 모델에 배정한다. 작업마다 목적·입력·제약·출력 형식을 전달한다. 결과를 검증하고 승인 단계에서 대기한다. 전송 정책과 호출 한도를 변경하지 않는다.')}</textarea><button data-action="saved" style="margin-top:15px">구성 저장</button></div></div>`;
case '생성 서버':return `<div class="card"><div class="card-head"><h2>remote ComfyUI</h2><span class="pill blue">영상 + Face QC</span></div><div class="fields"><div class="field"><label>서버 주소</label><input data-field="comfyUrl" value="${esc(state.comfyUrl||'http://192.168.0.20:8188')}"></div><div class="field"><label>인증</label><select><option>인증 없음 · 데모</option><option>Bearer token · 실제 연결에서 설정</option></select></div></div><div class="fields">${['이미지','영상','Face QC','입력 레퍼런스 노드'].map((n,i)=>`<div class="field"><label>${n} 워크플로</label><input data-workflow="${i}" value="${esc(state.workflows?.[i]||['character-reference.json','segment-15s.json','face-continuity-qc.json','reference_image'][i])}"></div>`).join('')}</div><div class="note">영상은 하나씩 생성하고 QC 통과 후 다음 구간을 시작합니다. 등록된 서버에 이미지·영상이 전송됩니다.</div><div class="actions"><small>실제 파일 업로드·실행 없음</small><button data-action="testComfy">연결·워크플로 검사</button></div></div>`;
default:return `<div class="card"><h2>콘텐츠가 이동하는 곳</h2><div class="field" style="margin-top:20px"><label>프로젝트 실행 경로</label><select data-field="mode">${options(['혼합','로컬 전용','클라우드'],state.mode)}</select></div><div class="checks"><div class="check"><span>클라우드 LLM에 내용 전달</span><b>${state.mode==='로컬 전용'?'차단':'명시적으로 배정한 단계만'}</b></div><div class="check"><span>로컬 실패 시 클라우드 자동 대체</span><b>항상 꺼짐</b></div><div class="check"><span>이미지·영상 전송 대상</span><b>지정된 ComfyUI</b></div></div><div class="note">로컬 전용에서도 remote ComfyUI가 다른 컴퓨터라면 그 서버로 자료가 이동해요. 정책은 요약·검수·재시도 결과에도 적용됩니다.</div><button style="margin-top:20px" data-action="saved">정책 저장</button></div>`;}}
function totalLength(){return state.statuses.reduce((n,_,i)=>n+(state.lengths?.[i]||15),0)}
function statusName(s){return {waiting:'이전 QC 대기',generating:'생성 중',internal:'내부 Face QC',boundary:'연결부 QC',pass:'QC 통과',fail:'검토 필요'}[s]||s}
function stop(){running=false;clearTimeout(timer)}
function run(){if(!running)return;let i=state.statuses.findIndex(s=>s!=='pass');if(i<0){stop();toast('모든 세그먼트 QC를 통과했어요.');render();return}state.selected=i;let s=state.statuses[i];if(s==='fail'){stop();render();return}if(i>0&&state.statuses[i-1]!=='pass'){stop();return}if(s==='waiting')state.statuses[i]='generating';else if(s==='generating')state.statuses[i]='internal';else if(s==='internal'){if(i===6&&!state.retry){state.statuses[i]='fail';stop()}else state.statuses[i]=i?'boundary':'pass'}else if(s==='boundary'){state.statuses[i]='pass';if(state.recheckNext){state.recheckNext=false;stop();toast('데모: 앞뒤 경계 재검사 완료. 해당 구간을 교체했어요.')}}render();if(running)timer=setTimeout(run,650)}
function modal(html){$('#modal').innerHTML=html;$('#modal').showModal()}
function act(a){if(a==='analyze'){if(!state.synopsis.trim())return toast('시놉시스를 먼저 적어 주세요.');state.analyzed=true;state.tab='플롯·스토리';state.storyApproved=false;toast('편집 가능한 데모 스토리를 만들었어요.')}if(a==='approveStory'){state.storyApproved=true;go('timeline')}if(a==='approveTimeline'){if(!state.storyApproved)return toast('스토리를 먼저 확정해 주세요.');if(totalLength()!==state.duration)return toast('샷 합계를 목표 시간에 맞춰 주세요.');state.timelineApproved=true;go('images')}if(a==='approveImage'){if(!state.timelineApproved)return toast('타임라인을 먼저 확정해 주세요.');state.imageApproved=true;toast('참조 v1을 영상과 QC에 연결했어요.');go('video')}if(a==='enhance'){state.imagePrompt=$('#imagePrompt').value+' 캐릭터의 얼굴과 의상을 유지. 부드러운 측면광, 눈높이 구도, 자연스러운 피부 질감.';state.enhanced=true;toast('로컬 강화 데모를 적용했어요.')}if(a==='generateImage'){if(state.mode==='로컬 전용'&&state.imageProvider!=='ComfyUI · 로컬')return toast('로컬 전용에서는 클라우드 이미지 요청이 차단됩니다.');state.imagePrompt=$('#imagePrompt').value;toast('후보 3개의 데모 프리뷰를 준비했어요.')}if(a==='start'){if(!state.imageApproved)return toast('레퍼런스를 먼저 확정해 주세요.');if(state.statuses.includes('fail'))return toast('실패한 세그먼트를 먼저 재생성해 주세요.');if(!running){running=true;run()}return}if(a==='pause'){stop();toast('현재 상태에서 잠시 멈췄어요.')}if(a==='retry'){stop();const i=state.selected;state.statuses[i]='waiting';if(i===6)state.retry=true;if(i<state.statuses.length-1&&state.statuses[i+1]==='pass'){state.recheckNext=true;running=true;run();return}else{running=true;run();return}}if(a==='saveLength'){const n=Number($('#clipDuration').value);if(!Number.isInteger(n)||n<1||n>30)return toast('1~30초 정수로 입력해 주세요.');state.lengths??={};state.lengths[state.selected]=n;state.timelineApproved=false;state.imageApproved=false;}if(a==='moveLeft'||a==='moveRight'){const to=state.selected+(a==='moveLeft'?-1:1);if(to<0||to>=state.statuses.length)return;[names[to],names[state.selected]]=[names[state.selected],names[to]];state.lengths??={};const oldLength=state.lengths[state.selected]||15;state.lengths[state.selected]=state.lengths[to]||15;state.lengths[to]=oldLength;state.selected=to;state.timelineApproved=false;toast('샷 순서를 바꿨어요.')}if(a==='new'){modal('<h2>새 이야기 시작하기</h2><p>현재 데모를 초기화하고 새 프로젝트를 시작합니다.</p><label>프로젝트 이름</label><input id="newTitle" value="나의 새로운 이야기"><div class="actions"><button data-action="close">취소</button><button class="primary" data-action="create">만들기</button></div>');return}if(a==='create'){const t=$('#newTitle').value.trim();if(!t)return;stop();state=fresh();state.title=t;state.synopsis='';$('#modal').close();go('story')}if(a==='addServer'){modal('<h2>로컬 모델 서버 등록</h2><p>주소는 실행 서버 기준입니다. 비밀값은 입력하지 마세요.</p><label>이름</label><input id="serverName" placeholder="예: 작업용 Ollama"><label style="margin-top:14px">서버 주소</label><input id="serverUrl" value="http://localhost:11434"><div class="actions"><button data-action="close">취소</button><button class="primary" data-action="saveServer">등록</button></div>');return}if(a==='saveServer'){let url;try{url=new URL($('#serverUrl').value);if(!['http:','https:'].includes(url.protocol))throw Error()}catch{return toast('올바른 HTTP 또는 HTTPS 주소를 입력해 주세요.')}state.connections.push({name:$('#serverName').value.trim()||'로컬 서버',url:url.href});$('#modal').close();toast('데모 서버를 등록했어요.')}if(a==='close')$('#modal').close();if(a==='saved')toast('이 브라우저에 데모 설정을 저장했어요.');if(a==='testComfy')toast('데모 검사 완료 · 워크플로 매핑 준비됨');if(a==='preview'){modal(`<h2>${names[state.selected%20]}</h2>${photo()}<p style="margin-top:15px">${time(state.selected*15)} — ${time((state.selected+1)*15)} · 장면 카드 프리뷰<br>카메라가 플랫폼을 따라 천천히 이동하며 윤의 시선을 따라갑니다.</p><button data-action="close">닫기</button>`);return}if(a==='downloadPalette'){const l=document.createElement('a');l.href='palette.svg';l.download='Framepop-color-chart.svg';l.click();return}render()}
document.addEventListener('click',async e=>{const b=e.target.closest('button,[data-candidate]');if(!b)return;if(b.dataset.page)go(b.dataset.page);else if(b.dataset.action)act(b.dataset.action);else if(b.dataset.tab){state.tab=b.dataset.tab;render()}else if(b.dataset.settingsTab){state.settingsTab=b.dataset.settingsTab;render()}else if(b.dataset.select!==undefined){state.selected=Number(b.dataset.select);render()}else if(b.dataset.candidate!==undefined){state.candidate=Number(b.dataset.candidate);state.imageApproved=false;render()}else if(b.dataset.copy){try{await navigator.clipboard.writeText(b.dataset.copy);toast('색상 코드 복사 완료')}catch{toast(b.dataset.copy)}}else if(b.dataset.auth){let n=b.dataset.auth;if(state.auth[n]){state.auth[n]=false;render();return}modal(`<h2>${n} 구독 연결 · 데모</h2><p>실제 로그인 페이지는 열지 않습니다. 기기 코드 승인 화면의 예시예요.</p><div class="code">DEMO-2026</div><p style="margin-top:15px">승인 대기 중 · 입력한 비밀값은 없습니다.</p><div class="actions"><button data-action="close">취소</button><button class="primary" id="approveAuth">데모 승인 완료</button></div>`);$('#approveAuth').onclick=()=>{state.auth[n]=true;$('#modal').close();render();toast('데모 계정 연결 완료')}}else if(b.dataset.test!==undefined)toast('데모 연결 검사 완료 · 실제 요청은 보내지 않았어요.');else if(b.dataset.models!==undefined)modal('<h2>사용 가능한 모델 · 데모</h2><p>로컬 텍스트 모델<br>로컬 프롬프트 강화 모델<br>실제 서버 목록은 연결 구현 후 조회됩니다.</p><button data-action="close">닫기</button>');else if(b.dataset.delete!==undefined){state.connections.splice(Number(b.dataset.delete),1);render()}});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.field){let k=t.dataset.field;state[k]=k==='duration'?Number(t.value):t.value;if(k==='duration'){stop();state.statuses=Array(Math.ceil(state.duration/15)).fill('waiting');state.selected=0;state.lengths={};state.storyApproved=state.timelineApproved=state.imageApproved=false}if(k==='mode'&&t.value==='로컬 전용'){state.primary='Ollama · 로컬 모델';state.roles=Array(5).fill('Ollama · 로컬 모델')}if(['synopsis','title'].includes(k)){state.storyApproved=false;state.timelineApproved=false;state.imageApproved=false}render()}else if(t.dataset.role!==undefined){state.roles??={};state.roles[t.dataset.role]=t.value;save()}else if(t.dataset.pipeline!==undefined){state.pipeline[t.dataset.pipeline]=t.value;save()}else if(t.dataset.workflow!==undefined){state.workflows??={};state.workflows[t.dataset.workflow]=t.value;save()}else if(t.dataset.beat!==undefined){state.beats??={};state.beats[t.dataset.beat]=t.value;state.storyApproved=false;state.timelineApproved=false;state.imageApproved=false;save()}});
document.addEventListener('keydown',e=>{if(e.target.matches('[data-candidate]')&&['Enter',' '].includes(e.key)){e.preventDefault();e.target.click()}});$('#reset').onclick=()=>{stop();state=fresh();go('story');render();toast('데모를 처음 상태로 되돌렸어요.')};window.addEventListener('hashchange',render);render();
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'navigate_framepop',description:'Navigate to a Framepop demo workspace screen.',inputSchema:{type:'object',properties:{page:{type:'string',enum:Object.keys(pages)}},required:['page'],additionalProperties:false},annotations:{readOnlyHint:false},execute:({page:p})=>{if(!Object.hasOwn(pages,p))throw Error('Invalid page');go(p);render();return{page:p,demo:true}}})}catch{}}
